152	export async function getProject(
153	  actor: Actor,
154	  orgId: OrgId,
155	  slug: string,
156	): Promise<ProjectWithStats> {
157	  assertOrgScope(actor, orgId);
158	
159	  const project = requireFound(
160	    await projectRepo.findProjectBySlug(orgId, slug),
