193	 * user sees while typing is what the row ends up with.
194	 */
195	export async function suggestProjectSlug(
196	  orgId: OrgId,
197	  name: string,
198	): Promise<string> {
199	  const taken = await projectRepo.listTakenProjectSlugs(orgId);
200	  return uniqueSlug(name, taken);
201	}

