    31	    const stamp = toIsoTimestamp(now);
    32	    const expiring = await subscriptionRepo.listTrialsEndingBefore(stamp);
    33	    const freeLimits = getPlanLimits(FALLBACK_PLAN);
    34	
    35	    for (const subscription of expiring) {
    36	      const orgId = subscription.orgId as OrgId;
    37	      const usage = await usageRepo.getUsage(orgId);
    38	
    39	      if (
    40	        usage.seatsUsed > freeLimits.seats ||
    41	        usage.projectsUsed > freeLimits.projects
    42	      ) {
    43	        result.failed += 1;
    44	        logger.warn("trial expired but tenant is over the free plan", {
    45	          orgId,
    46	          seats: usage.seatsUsed,
    47	          projects: usage.projectsUsed,
    48	        });
    49	        continue;
    50	      }
    51	
    52	      await subscriptionRepo.updateSubscriptionPlan(
    53	        orgId,
    54	        FALLBACK_PLAN,
    55	        subscription.interval,
    56	      );
    57	
    58	      await emit("billing.plan_changed", {
    59	        orgId,
    60	        actorId: null,
    61	        occurredAt: stamp,
    62	        from: subscription.plan,
